using NUnit.Framework;using UnityEngine;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
namespace OneMoreTime.Tests {
public class InputTests : InputTestFixture {
 bool hadPreferences;string savedPreferences;
 [SetUp]public override void Setup(){base.Setup();hadPreferences=PlayerPrefs.HasKey(KeyBindings.PreferencesKey);savedPreferences=PlayerPrefs.GetString(KeyBindings.PreferencesKey, "");PlayerPrefs.DeleteKey(KeyBindings.PreferencesKey);KeyBindings.Reload();}
 [TearDown]public override void TearDown(){base.TearDown();if(hadPreferences)PlayerPrefs.SetString(KeyBindings.PreferencesKey,savedPreferences);else PlayerPrefs.DeleteKey(KeyBindings.PreferencesKey);PlayerPrefs.Save();KeyBindings.Reload();}
 [Test]public void DownJumpIsConsumedOnce(){var previous=Keyboard.current;var keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();try{var adapter=new KeyboardPlayerInput();InputSystem.QueueStateEvent(keyboard,new KeyboardState(KeyBindings.Get(GameAction.MoveDown),KeyBindings.Get(GameAction.Jump)));InputSystem.Update();adapter.Poll();var first=adapter.Consume();Assert.IsTrue(first.drop);Assert.IsTrue(first.jump);Assert.IsFalse(adapter.Consume().drop);adapter.Clear();adapter.Poll();Assert.IsFalse(adapter.Consume().drop);}finally{InputSystem.RemoveDevice(keyboard);if(previous!=null)previous.MakeCurrent();}}
 [Test]public void HeldKeysAndResetSuppression(){var previous=Keyboard.current;var keyboard=InputSystem.AddDevice<Keyboard>();keyboard.MakeCurrent();try{var adapter=new KeyboardPlayerInput();InputSystem.QueueStateEvent(keyboard,new KeyboardState(KeyBindings.Get(GameAction.Shutter)));InputSystem.Update();Assert.IsTrue(keyboard[KeyBindings.Get(GameAction.Shutter)].isPressed,"Synthetic shutter state must be visible");Assert.AreSame(keyboard,Keyboard.current,"Fixture keyboard must be current");adapter.Poll();Assert.IsTrue(adapter.Consume().freeze,"Initial shutter edge");InputSystem.Update();adapter.Poll();Assert.IsFalse(adapter.Consume().freeze);adapter.Clear();InputSystem.QueueStateEvent(keyboard,new KeyboardState(KeyBindings.Get(GameAction.RecordReplay),KeyBindings.Get(GameAction.MoveRight),KeyBindings.Get(GameAction.Jump)));InputSystem.Update();adapter.Poll();var blocked=adapter.Consume();Assert.IsFalse(blocked.trace);Assert.IsFalse(blocked.jump);Assert.AreEqual(0,blocked.move);InputSystem.QueueStateEvent(keyboard,new KeyboardState());InputSystem.Update();adapter.Poll();InputSystem.QueueStateEvent(keyboard,new KeyboardState(KeyBindings.Get(GameAction.RecordReplay)));InputSystem.Update();adapter.Poll();Assert.IsTrue(adapter.Consume().trace);Assert.IsFalse(adapter.Consume().trace);}finally{InputSystem.RemoveDevice(keyboard);if(previous!=null)previous.MakeCurrent();}}
}
}
